// Edit/extend this list freely. Public listing pages only, read-only.
const SITES = [
  ['Mostaql',   'https://mostaql.com/projects'],
  ['Khamsat',   'https://khamsat.com/community/requests'],
  ['Nafezly',   'https://nafezly.com/projects'],
  ['Kafiil',    'https://kafiil.com/'],
  ['Freelancer','https://www.freelancer.com/jobs/'],
  ['Upwork',    'https://www.upwork.com/freelance-jobs/'],
  ['Fiverr',    'https://www.fiverr.com/']
];
return SITES.map(([name, url]) => ({ json: { name, url } }));

const sites = $('Sites').all();
const chat = $('Load Owner').first().json.telegram_id;
const lines = ['🔎 نتيجة فحص المواقع (قراءة فقط)\n'];
$input.all().forEach((it, i) => {
  const s = sites[i].json;
  const status = it.json.statusCode ?? (it.json.error ? 'ERR' : '?');
  const body = String(it.json.body ?? it.json.data ?? '');
  const title = (body.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [,''])[1].replace(/\s+/g,' ').trim().slice(0, 60);
  const blocked = /just a moment|cf-chl|challenge-platform|captcha|access denied|are you a robot/i.test(body);
  const anchors = [...body.matchAll(/<a\s[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)]
    .map(m => ({ href: m[1], text: m[2].replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim() }))
    .filter(a => a.text.length >= 15);
  const verdict = status !== 200 ? '❌ مش بيرد (' + status + ')' : blocked ? '🚫 فيه حماية بتمنع البوت' : anchors.length < 5 ? '⚠️ الصفحة فاضية (غالبًا JavaScript)' : '✅ شغال';
  lines.push(`${s.name}: ${verdict}\nحجم: ${body.length} | روابط: ${anchors.length}${title ? ' | ' + title : ''}`);
  if (verdict.startsWith('✅')) lines.push('أمثلة: ' + anchors.slice(0, 3).map(a => a.text.slice(0, 40)).join(' || '));
  lines.push('');
});
return [{ json: { chat, text: lines.join('\n').slice(0, 3900) } }];
